-- Reference snapshot of the live Compass schema, generated by introspecting
-- the production Supabase project (npeegfsoijhdnnvuqjin) on 2026-08-06.
--
-- WHY THIS FILE EXISTS: every other file in supabase/ is an ALTER against a
-- base schema that was never itself committed — the base CREATE TABLEs for
-- cases, organisations, org_members, locations, employee_records,
-- hr_review_requests, profiles, and signing_requests only ever existed in
-- the live project (built via the dashboard/CLI without migration
-- tracking; `list_migrations` only goes back to 2026-08-04). That means the
-- schema could not be reproduced from this repo alone — no staging
-- environment, no way to safely test an RLS change before applying it live.
--
-- This file closes that gap for reference and disaster-recovery purposes.
-- IMPORTANT CAVEATS:
--   1. This is a best-effort snapshot generated via information_schema /
--      pg_catalog introspection, not a certified `pg_dump`. It's a reliable
--      reference, but treat it as documentation, not as something to blindly
--      replay — table order below is dependency-safe, but sequences,
--      extension versions, and some storage/auth-schema internals are not
--      captured.
--   2. For an authoritative, tool-generated baseline, run from a machine
--      with the Supabase CLI:
--        supabase link --project-ref npeegfsoijhdnnvuqjin
--        supabase db pull
--      That uses pg_dump against the real project and will produce a
--      migration Supabase's own tooling considers canonical — prefer it
--      over this file if the two ever disagree.
--   3. Do not run this file against the live project — the tables already
--      exist there. It's meant for spinning up a local/staging Postgres to
--      develop and test schema changes against before they go live.

-- ── Tables (dependency order) ──────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.organisations (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  name text NOT NULL,
  invite_code text NOT NULL,
  created_at timestamp with time zone DEFAULT now(),
  created_by uuid,
  notification_webhook_url text,
  notification_webhook_type text,
  plan text NOT NULL DEFAULT 'free'::text,
  stripe_customer_id text,
  stripe_subscription_id text,
  stripe_subscription_status text,
  CONSTRAINT organisations_pkey PRIMARY KEY (id),
  CONSTRAINT organisations_invite_code_key UNIQUE (invite_code),
  CONSTRAINT organisations_created_by_fkey FOREIGN KEY (created_by) REFERENCES auth.users(id)
);

CREATE TABLE IF NOT EXISTS public.profiles (
  id uuid NOT NULL,
  name text,
  role text DEFAULT 'hr_manager'::text,
  company text,
  created_at timestamp with time zone DEFAULT now(),
  CONSTRAINT profiles_pkey PRIMARY KEY (id),
  CONSTRAINT profiles_id_fkey FOREIGN KEY (id) REFERENCES auth.users(id)
);
-- NOTE: unreferenced by any client or api/ code as of this snapshot — no
-- signup path currently writes to it (handle_new_user's trigger doesn't
-- exist in the live DB; see the function definition below). Kept here for
-- schema fidelity, but likely safe to drop along with handle_new_user()
-- after confirming nothing depends on it.

CREATE TABLE IF NOT EXISTS public.org_members (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  org_id uuid,
  user_id uuid,
  role text DEFAULT 'hr_manager'::text,
