-- ── Helper functions (SECURITY DEFINER, used inside RLS policies) ──────

CREATE OR REPLACE FUNCTION public.my_org_ids()
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select org_id from public.org_members where user_id = auth.uid()
$function$;

CREATE OR REPLACE FUNCTION public.org_has_members(p_org_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.org_members where org_id = p_org_id)
$function$;

CREATE OR REPLACE FUNCTION public.can_access_case_location(p_org_id uuid, p_location_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- Members without a role-scoped location list (i.e. anyone who isn't a
  -- location_manager with locations assigned) see every location, matching
  -- current app behaviour where only location_manager is filtered client-side.
  SELECT NOT EXISTS (
    SELECT 1 FROM org_members om
    WHERE om.org_id = p_org_id
      AND om.user_id = auth.uid()
      AND om.role = 'location_manager'
      AND om.location_ids IS NOT NULL
      AND array_length(om.location_ids, 1) > 0
  )
  OR EXISTS (
    SELECT 1 FROM org_members om
    WHERE om.org_id = p_org_id
      AND om.user_id = auth.uid()
      AND p_location_id = ANY(om.location_ids)
  );
$function$;

CREATE OR REPLACE FUNCTION public.check_rate_limit(p_key text, p_limit integer, p_window_seconds integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count int;
begin
  insert into public.api_rate_limits (rate_key, window_start, request_count)
  values (p_key, now(), 1)
  on conflict (rate_key) do update
    set request_count = case
          when public.api_rate_limits.window_start <= now() - make_interval(secs => p_window_seconds)
            then 1
          else public.api_rate_limits.request_count + 1
        end,
        window_start = case
          when public.api_rate_limits.window_start <= now() - make_interval(secs => p_window_seconds)
            then now()
          else public.api_rate_limits.window_start
        end
  returning request_count into v_count;

  return v_count <= p_limit;
end;
$function$;

CREATE OR REPLACE FUNCTION public.join_org_with_invite_code(p_invite_code text, p_name text)
 RETURNS TABLE(org_id uuid, org_name text, org_invite_code text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_org record;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  if not check_rate_limit('join_org:' || auth.uid()::text, 10, 300) then
    raise exception 'Too many attempts — please wait a few minutes and try again.';
  end if;

  select id, name, invite_code into v_org
  from organisations
  where invite_code = upper(trim(p_invite_code));

  if v_org.id is null then
    raise exception 'Invalid invite code';
  end if;

  if exists (
    select 1 from org_members
    where org_members.org_id = v_org.id and org_members.user_id = auth.uid()
  ) then
    raise exception 'You are already a member of this organisation';
  end if;

  insert into org_members (org_id, user_id, role, name)
  values (v_org.id, auth.uid(), 'location_manager', trim(p_name));

  return query select v_org.id, v_org.name, v_org.invite_code;
end;
$function$;

-- Auth trigger function — no trigger currently wires it to auth.users in
-- the live DB (verified 2026-08-06: zero non-internal triggers on
-- auth.users besides FK constraint triggers), and nothing in src/ or api/
-- reads public.profiles. Kept for schema fidelity; EXECUTE is revoked from
-- anon/authenticated (2026-08-06 migration) since it isn't meant to be
-- called directly either way.
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into profiles (id, name, company)
  values (
    new.id,
    coalesce(new.raw_user_meta_data->>'name', ''),
    coalesce(new.raw_user_meta_data->>'company', '')
  )
  on conflict (id) do nothing;
  return new;
end;
$function$;
REVOKE EXECUTE ON FUNCTION public.handle_new_user() FROM public, anon, authenticated;

CREATE OR REPLACE FUNCTION public.protect_billing_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.role() <> 'service_role' then
    if new.plan is distinct from old.plan
      or new.stripe_customer_id is distinct from old.stripe_customer_id
      or new.stripe_subscription_id is distinct from old.stripe_subscription_id
      or new.stripe_subscription_status is distinct from old.stripe_subscription_status
    then
      raise exception 'Billing fields can only be changed by the billing system';
    end if;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.protect_org_member_privilege_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if (new.role is distinct from old.role) or (new.location_ids is distinct from old.location_ids) then
    if auth.role() <> 'service_role' and not exists (
      select 1 from public.org_members
      where org_id = old.org_id and user_id = auth.uid() and role in ('hr_director','hr_manager')
    ) then
      raise exception 'Only an HR Director or HR Manager can change a member''s role or location access';
    end if;
  end if;
  return new;
end;
$function$;

CREATE TRIGGER protect_billing_columns_trigger BEFORE UPDATE ON public.organisations
  FOR EACH ROW EXECUTE FUNCTION protect_billing_columns();

CREATE TRIGGER protect_org_member_privilege_columns_trigger BEFORE UPDATE ON public.org_members
  FOR EACH ROW EXECUTE FUNCTION protect_org_member_privilege_columns();

-- ── RLS policies ────────────────────────────────────────────────────────

CREATE POLICY organisations_insert_own ON public.organisations FOR INSERT
  WITH CHECK (created_by = auth.uid());
CREATE POLICY organisations_select_member_or_creator ON public.organisations FOR SELECT
  USING (id IN (SELECT my_org_ids()) OR created_by = auth.uid());
CREATE POLICY organisations_update_member ON public.organisations FOR UPDATE
  USING (id IN (SELECT my_org_ids())) WITH CHECK (id IN (SELECT my_org_ids()));

CREATE POLICY "Own profile" ON public.profiles FOR ALL
  USING (auth.uid() = id);

CREATE POLICY org_members_select_same_org ON public.org_members FOR SELECT
  USING (org_id IN (SELECT my_org_ids()));
CREATE POLICY org_members_update_same_org ON public.org_members FOR UPDATE
  USING (org_id IN (SELECT my_org_ids()));
CREATE POLICY org_members_insert_founding_member ON public.org_members FOR INSERT
  WITH CHECK (
    user_id = auth.uid() AND role = 'hr_director'
    AND NOT org_has_members(org_id)
    AND org_id IN (SELECT id FROM organisations WHERE created_by = auth.uid())
  );

CREATE POLICY org_roles_same_org ON public.org_roles FOR ALL
  USING (org_id IN (SELECT my_org_ids())) WITH CHECK (org_id IN (SELECT my_org_ids()));

CREATE POLICY locations_same_org ON public.locations FOR ALL
  USING (org_id IN (SELECT my_org_ids())) WITH CHECK (org_id IN (SELECT my_org_ids()));

CREATE POLICY "Users can manage employee records in their org" ON public.employee_records FOR ALL
  USING (org_id IN (SELECT my_org_ids()));

-- cases: two policies combine — the ALL policy (permissive) grants access,
-- the SELECT policy (restrictive) further narrows confidential rows. See
-- can_access_case_location() above for the location-scoping logic
-- (2026-08-06 fix — previously org-wide for every member regardless of role).
CREATE POLICY "Users can access cases in their org or assigned to them" ON public.cases FOR ALL
  USING (
    (org_id IN (SELECT my_org_ids()) AND can_access_case_location(org_id, location_id))
    OR id IN (SELECT case_id FROM case_access WHERE user_id = auth.uid())
  );
CREATE POLICY "Confidential cases restricted to authorised staff" ON public.cases AS RESTRICTIVE FOR SELECT
  USING (
    confidential = false
    OR created_by = auth.uid()
    OR EXISTS (SELECT 1 FROM case_access ca WHERE ca.case_id = cases.id AND ca.user_id = auth.uid())
    OR EXISTS (SELECT 1 FROM org_members om WHERE om.org_id = cases.org_id AND om.user_id = auth.uid() AND om.role = 'hr_director')
  );

CREATE POLICY "Own meetings" ON public.meetings FOR ALL
  USING (case_id IN (SELECT id FROM cases WHERE user_id = auth.uid()));
-- NOTE: this policy is effectively unreachable dead code — meetings is an
-- unused table (see its CREATE TABLE comment above) and cases.user_id is
-- itself vestigial (the app scopes by org_id/created_by, not user_id).

CREATE POLICY "Users can view case access in their org" ON public.case_access FOR SELECT
  USING (org_id IN (SELECT my_org_ids()));
CREATE POLICY "Users can grant case access in their org" ON public.case_access FOR INSERT
  WITH CHECK (org_id IN (SELECT my_org_ids()));
CREATE POLICY "Users can revoke case access in their org" ON public.case_access FOR DELETE
  USING (org_id IN (SELECT my_org_ids()));

CREATE POLICY hr_review_requests_same_org ON public.hr_review_requests FOR ALL
  USING (org_id IN (SELECT my_org_ids())) WITH CHECK (org_id IN (SELECT my_org_ids()));

CREATE POLICY dsar_requests_same_org ON public.dsar_requests FOR ALL
  USING (org_id IN (SELECT my_org_ids())) WITH CHECK (org_id IN (SELECT my_org_ids()));

CREATE POLICY "Users can manage starter instances in their org" ON public.starter_instances FOR ALL
  USING (org_id IN (SELECT my_org_ids()));
CREATE POLICY "Users can manage leaver instances in their org" ON public.leaver_instances FOR ALL
  USING (org_id IN (SELECT my_org_ids()));

CREATE POLICY audit_log_select_org_member ON public.audit_log FOR SELECT
  USING (org_id IN (SELECT my_org_ids()));
CREATE POLICY audit_log_insert_self ON public.audit_log FOR INSERT
  WITH CHECK (org_id IN (SELECT my_org_ids()) AND user_id = auth.uid());

-- employee_portal_invites, employee_portal_accounts, signing_requests,
-- api_rate_limits, calendar_connections, calendar_synced_events: RLS
-- enabled with zero policies (client-facing access fully denied by
-- default). All reads/writes go through api/portal/*, api/signing.js, and
-- api/calendar/* using the service-role key, which bypasses RLS entirely —
-- by design, not an oversight (see file-level comments on each table above
-- and api/signing.js's header comment).
